public enum Direction { Up, Down, Idle }

public class Request
{
    public int Floor { get; }
    public Direction Direction { get; }
    public bool IsInternal { get; }

    public Request(int floor, Direction direction, bool isInternal = false)
    {
        Floor = floor;
        Direction = direction;
        IsInternal = isInternal;
    }
}

public class Elevator
{
    private readonly SortedSet<int> _upStops = new();
    private readonly SortedSet<int> _downStops = new(new Comparer());
    public int CurrentFloor { get; private set; } = 1;
    public Direction Direction { get; private set; } = Direction.Idle;
    public int Capacity { get; } = 8;
    public int CurrentLoad { get; private set; }

    public void AddRequest(Request request)
    {
        if (CurrentLoad >= Capacity)
            throw new InvalidOperationException("Elevator full");

        if (request.Direction == Direction.Up)
            _upStops.Add(request.Floor);
        else
            _downStops.Add(request.Floor);
    }

    public void Step()
    {
        if (Direction == Direction.Up && _upStops.Count == 0)
            Direction = _downStops.Count > 0 ? Direction.Down : Direction.Idle;
        if (Direction == Direction.Down && _downStops.Count == 0)
            Direction = _upStops.Count > 0 ? Direction.Up : Direction.Idle;

        if (Direction == Direction.Up && _upStops.TryGetValue(out var nextUp))
        {
            CurrentFloor = nextUp;
            _upStops.Remove(nextUp);
        }
        else if (Direction == Direction.Down && _downStops.TryGetValue(out var nextDown))
        {
            CurrentFloor = nextDown;
            _downStops.Remove(nextDown);
        }
    }

    private class Comparer : IComparer<int>
    {
        public int Compare(int x, int y) => y.CompareTo(x); // descending for down stops
    }
}
